    /// Creates a new instance
    pub const fn new(name: String, funder_kind: FunderKind) -> Self {
        Self { name, funder_kind }
    }

    #[must_use]
    /// Gets funder name
    pub fn name(&self) -> &str {
        &self.name
    }

    #[must_use]
    /// Gets legal person
