  background: #5c277f;
}
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.skip-link {
  position: absolute;
  left: 24px;
  top: 16px;
  transform: translateY(-180%);
  padding: 12px 16px;
  background: var(--surface);
  z-index: 2;
}
.skip-link:focus {
  transform: none;
}
.app-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: 0 auto;
  padding: 0 64px;
  display: flex;
  flex-direction: column;
}
.app-header {
  display: flex;
