  ],
};

async function mockDetails(context: Parameters<Parameters<typeof test>[1]>[0]["context"]) {
  await context.route("**/api/search?*", route => route.fulfill({ json: { entities: [{ id: "1", name: member.name, kind: "MP", funder_kind: null }, { id: funderId, name: "Exact Funder", kind: "Funder", funder_kind: "Company" }] } }));
  await context.route("**/api/members/*", route => route.fulfill({ json: memberDetails }));
  await context.route("**/api/funders/*", route => route.fulfill({ json: funderDetails }));
}

test("native links preserve search and threshold through details, back, reload and new tabs", async ({ page, context }) => {
  await mockDetails(context);
  await page.goto("/?q=Example&strictness=0.42");
  const link = page.getByRole("link", { name: "Ava Example", exact: true });
  await expect(link).toHaveAttribute("href", "/members/1?q=Example&strictness=0.42");
  await expect(page.locator(".entity-name button")).toHaveCount(0);
  const popupPromise = page.waitForEvent("popup");
  await link.click({ modifiers: ["ControlOrMeta"] });
  const popup = await popupPromise;
  await expect(popup.getByRole("heading", { name: member.name, exact: true })).toBeVisible();
  await popup.close();
  await link.click();
  await expect(page).toHaveURL(/\/members\/1\?q=Example&strictness=0.42$/u);
  await expect(page.getByRole("heading", { name: "Recent declarations" })).toBeVisible();
  await page.reload();
  await expect(page.getByRole("heading", { name: member.name, exact: true })).toBeVisible();
  await page.getByRole("link", { name: "Exact Funder", exact: true }).first().click();
  await expect(page.getByRole("heading", { name: "Declared support by party" }).first()).toBeVisible();
  await expect(page).toHaveURL(new RegExp(`/funders/${funderId}\\?q=Example&strictness=0.42$`, "u"));
  await page.getByRole("link", { name: "Ava Example", exact: true }).click();
  await expect(page.getByRole("heading", { name: member.name, exact: true })).toBeVisible();
  await page.getByRole("link", { name: "Back to search", exact: true }).click();
  await expect(page.getByRole("searchbox")).toHaveValue("Example");
  await expect(page.getByRole("slider")).toHaveValue("0.42");
  await link.click();
  await expect(page.getByRole("heading", { name: member.name, exact: true })).toBeVisible();
  await page.goBack();
  await expect(page.getByRole("searchbox")).toHaveValue("Example");
});

test("member declarations retain duplicate precise amounts and missing source fields", async ({ page, context }) => {
  await mockDetails(context);
  await page.goto("/members/1");
  await expect(page.locator(".profile-type")).toHaveText("MP");
  await expect(page.getByText("Latest 20 at most, of 24 stored declarations.")).toBeVisible();
  await expect(page.locator(".funding-value .amount")).toHaveText(["9,007,199,254,740,993.123456789", "9,007,199,254,740,993.123456789", "Amount unavailable"]);
  await expect(page.getByText("21 Jan 2026", { exact: true })).toBeVisible();
  await expect(page.getByText("Registration date unavailable")).toBeVisible();
  await expect(page.getByText("Funder unavailable")).toBeVisible();
  await expect(page.getByText("Currency unavailable")).toBeVisible();
  await expect(page.getByText("Payment type unavailable")).toBeVisible();
  await expect(page.getByText("No funding entries recorded.")).toBeVisible();
  await expect(page.getByRole("heading", { name: "Top recipients" })).toHaveCount(0);
});

test("funder currencies keep exact totals, local missing amounts, zero and negatives", async ({ page, context }) => {
  await mockDetails(context);
  await page.goto(`/funders/${funderId}`);
  await expect(page.locator(".profile-type")).toHaveText("Funder");
  await expect(page.getByText("00123456", { exact: true })).toBeVisible();
  await expect(page.getByText("2 entries have an unknown currency and are excluded from totals and rankings.")).toBeVisible();
  const gbp = page.getByRole("region", { name: "GBP declared support", exact: true });
  await expect(gbp.locator(".amount")).toHaveText(["18,014,398,509,481,986.246913578", "−5", "18,014,398,509,481,986.246913578", "0"]);
  await expect(gbp.locator(".partial-note")).toHaveText(["1 amount unavailable", "1 amount unavailable"]);
  const eur = page.getByRole("region", { name: "EUR declared support", exact: true });
  await expect(eur.locator(".amount")).toHaveText(["Amount unavailable", "Amount unavailable"]);
  await expect(eur.locator(".partial-note")).toHaveText(["1 amount unavailable", "1 amount unavailable"]);
  await expect(page.getByRole("region", { name: "USD declared support" }).getByRole("link", { name: "Bea Example" })).toBeVisible();
  await expect(page.getByText(/Parties do not describe membership/u)).toBeVisible();
  await expect(page.getByRole("heading", { name: "Recent declarations" })).toHaveCount(0);
});

test("errors allow retry, not found and invalid routes have useful search navigation", async ({ page }) => {
  let calls = 0;
  await page.route("**/api/members/*", async route => {
    calls += 1;
    await route.fulfill(calls === 1 ? { status: 503, body: "private database error" } : { json: memberDetails });
  });
  await page.goto("/members/1?q=Example&strictness=0.4");
  await expect(page.getByRole("alert")).toContainText("Details couldn’t load");
  await expect(page.getByText("private database error")).toHaveCount(0);
  await page.getByRole("button", { name: "Try again" }).click();
  await expect(page.getByRole("heading", { name: member.name, exact: true })).toBeVisible();
  await page.route("**/api/members/999", route => route.fulfill({ status: 404 }));
  await page.goto("/members/999?q=Example");
  await expect(page.getByRole("heading", { name: "Entity not found" })).toBeVisible();
  await expect(page.getByRole("link", { name: "Search MPs and funders", exact: true })).toHaveAttribute("href", "/?q=Example");
  await page.goto("/members/0");
  await expect(page.getByRole("heading", { name: "Entity not found" })).toBeVisible();
  expect(calls).toBe(2);
});

test("empty details and unknown currency only details remain distinct from errors", async ({ page }) => {
  await page.route("**/api/members/1", route => route.fulfill({ json: { ...memberDetails, declarations: [], declaration_count: 0 } }));
  await page.route("**/api/funders/*", route => route.fulfill({ json: { ...funderDetails, currencies: [], entry_count: 0, unknown_currency_count: 0 } }));
  await page.goto("/members/1");
  await expect(page.getByText("No declarations are stored for this MP.")).toBeVisible();
  await page.goto(`/funders/${funderId}`);
  await expect(page.getByText("No funding entries are stored for this funder.")).toBeVisible();
  await page.route("**/api/funders/*", route => route.fulfill({ json: { ...funderDetails, currencies: [], entry_count: 2, unknown_currency_count: 2 } }));
  await page.reload();
  await expect(page.getByText("No known currencies are available for totals or rankings.")).toBeVisible();
  await expect(page.getByText("2 entries have an unknown currency and are excluded from totals and rankings.")).toBeVisible();
});

test("malformed responses and mismatched identities fail at the boundary", async ({ page }) => {
  await page.route("**/api/members/*", route => route.fulfill({ json: { ...memberDetails, member: { ...member, id: "2" } } }));
  await page.goto("/members/1");
  await expect(page.getByRole("alert")).toContainText("unexpected response");
  await page.route("**/api/funders/*", route => route.fulfill({ json: { ...funderDetails, currencies: [{ currency: "GBP", parties: [{ party_name: "Party A", amount: 9007199254740993, entry_count: 1, unknown_amount_count: 0 }], top_recipients: [] }] } }));
  await page.goto(`/funders/${funderId}`);
  await expect(page.getByRole("alert")).toContainText("unexpected response");
});

test("long names and exact amounts fit a narrow screen and source markup stays literal", async ({ page }) => {
  const longName = 'Association <img src=x onerror="alert(1)"> for Research and Public Interest Organisations';
  await page.setViewportSize({ width: 360, height: 780 });
  await page.route("**/api/funders/*", route => route.fulfill({ json: { ...funderDetails, funder: { ...funderDetails.funder, name: longName }, currencies: funderDetails.currencies.map(group => ({ ...group, parties: group.parties.map(party => ({ ...party, party_name: "The Party of Research and Public Interest Organisations" })) })) } }));
  await page.goto(`/funders/${funderId}`);
  await expect(page.getByRole("heading", { name: longName, exact: true })).toBeVisible();
  await expect(page.locator("#details img")).toHaveCount(0);
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true);
  await page.route("**/api/members/*", route => route.fulfill({ json: { ...memberDetails, member: { ...member, name: longName } } }));
  await page.goto("/members/1");
  await expect(page.getByRole("heading", { name: longName, exact: true })).toBeVisible();
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true);
  await page.keyboard.press("/");
  await expect(page.getByRole("searchbox")).toHaveCount(0);
